/**
 * N_a = Σ_n U_n · C_{subject,n} · μ_{subject,n}   (§23 Need term)
 *
 * `expectationsForSubject` supplies, for each Need the character currently
 * has, the learned NeedExpectation of this Action's subject against that
 * Need (defaulting to μ=0, τ=0 ⇒ contribution 0 for anything never
 * experienced — see model/expectation.ts).
 */
export function evaluateAction(
  action: ActionDef,
  needContexts: readonly NeedContext[],
  expectationsForSubject: (needId: NeedId) => NeedExpectation,
  kC: Rational,
): ScoredAction {
  const perNeedContributions = needContexts.map(({ def, urgency }) => {
    const exp = expectationsForSubject(def.needId);
    const c = confidence(exp.tau, kC);
    const contribution = urgency.mul(c).mul(exp.mu);
    return { needId: def.needId, urgency, confidence: c, mu: exp.mu, contribution };
  });

  const needTerm = perNeedContributions.reduce((acc, c) => acc.add(c.contribution), Rational.ZERO);
  const score = needTerm; // Phase 1: Score(a) = N_a only.
  const boundedScore = Rational.boundedResponse(score);

  return {
    actionKey: action.actionKey,
    needTerm,
    score,
    boundedScore,
    perNeedContributions,
  };

/**
 * Brief §28 primary Phase-1 experiment: "Mina repeatedly experiences Glen
 * satisfying Connection." Runs N forced (scripted) Experiences of one
 * Action and returns the full per-step trace so the UI can chart μ, τ,
 * confidence, and Need level over time.
 */

import { CanonicalActionKey, ConceptKey } from '../kernel/canonical';
import { CharacterState } from '../model/character';
import { ActionDef } from '../model/actions';
import { WorldOutcomeTable } from '../model/outcome';
import { CycleParams, CycleResult, runScriptedExperience } from '../model/cycle';
import { EventClock } from '../kernel/event';

export interface ExperimentStep {
  readonly index: number;
  readonly result: CycleResult;
}

export function runLearnedSatisfactionExperiment(
  actor: ConceptKey,
  initialState: CharacterState,
  action: ActionDef,
  outcomeTable: WorldOutcomeTable,
  params: CycleParams,
  seed: string,
  steps: number,
  clock: EventClock = new EventClock(),
): { finalState: CharacterState; steps: ExperimentStep[] } {
  let state = initialState;
  const history: ExperimentStep[] = [];
  for (let i = 0; i < steps; i++) {
    clock.advance(1);
    const result = runScriptedExperience(actor, state, action, outcomeTable, params, clock, seed);
    state = result.nextState;
    history.push({ index: i, result });
  }
  return { finalState: state, steps: history };
}

for (let i = 0; i < needLevelsBefore.length; i++) {
  const needLevelBefore = needLevelsBefore[i];
  clock.advance(1);
  state = withNeedLevel(state, focusNeed, needLevelBefore);
  // Seed is addressed by (timeline, repetition index) only, NOT by
  // learningMode: naive and censored must replay the exact same random
  // outcome-noise draws at each repetition, per Brief §29's paired-
  // counterfactual methodology (Phase 0-2 already establishes this
  // pattern) — otherwise a divergence in learned mu could be an artifact
  // of different noise draws rather than of the learning rule itself.
  const result = runScriptedExperience(actor, state, satisfierAction, satisfierOutcome, modeParams, clock, `${seed}:${timeline}:${i}`);

  it('a single fresh-prior observation makes censoring a mu-no-op at every starting Level, but (Correction 2) NOT a confidence-no-op at total saturation', () => {
    // The key structural finding that motivates the counterfactual
    // experiment below: the one-sided update rule can only ever REJECT a
    // naive candidate that would move mu to the wrong side of the CURRENT
    // prior. A brand-new NeedExpectation(subject, need) starts at mu=0, and
    // every candidate here is a non-negative Applied value, so the naive
    // candidate is always >= the fresh prior — mu itself is therefore
    // identical between learningModes at every starting Level, fresh-prior
    // or not (censoring's protective effect on MU only has something to
    // protect once a real expectation has already been established; see the
    // counterfactual test below, which builds that prior first).
    //
    // CONFIDENCE is a different story since Correction 2 (post-2.5c review):
    // at needLevelBefore=1 the Need has no headroom at all, so Applied=0
    // exactly — the naive candidate lands EXACTLY on the fresh prior mu=0,
    // which is the boundary case Correction 2 classifies as UNINFORMATIVE
    // ("the effect was at least 0" proves nothing when you already believe
    // 0). 'naive' mode always uses 'point' evidence regardless of
    // saturation, so it still (incorrectly, per Brief §27's own spirit)
    // grows confidence from this zero-information observation; 'censored'
    // mode correctly recognizes it as uninformative and grows no confidence
    // at all — this is Phase 2.5a's Correction section's "Case C" made
    // concrete inside the sweep experiment itself, not just in a unit test.
    const { scenario, initial, glenAction, stayHomeAction, glenOutcome } = setup();
    const levels = [ratOf(1, 10), ratOf(4, 10), ratOf(7, 10), ratOf(9, 10), ratOf(1)];

    const result = runSaturatedSatisfactionExperiment(
      PERSON_MINA,
      initial,
      glenAction,
      glenOutcome,
      stayHomeAction,
      NEED_CONNECTION,
      levels,
      scenario.cycleParams,
      'saturation-sweep-seed',
    );

    for (const level of levels) {
      const naive = result.points.find((p) => p.learningMode === 'naive' && p.needLevelBefore.equals(level))!;
      const censored = result.points.find((p) => p.learningMode === 'censored' && p.needLevelBefore.equals(level))!;
      expect(censored.mu.equals(naive.mu)).toBe(true);
      if (level.equals(Rational.ONE)) {
        // Total saturation: naive wrongly grows confidence from a
        // zero-information observation; censored correctly does not.
        expect(censored.confidence.isZero()).toBe(true);
        expect(naive.confidence.gt(censored.confidence)).toBe(true);
      } else {
        expect(censored.confidence.equals(naive.confidence)).toBe(true);
      }
    }
  });
});

