/** T_j = boundedResponse(b_j + w_j^T·I + I^T·Q_j·I) — Brief §21, the same
 * quadratic-projection shape the master Brief §9.1 specifies for
 * personality trait labels, applied here to the IdentityStrength vector
 * instead. `w`/`Q` are dense over `CHANNEL_ORDER`. A simple single-channel
 * trait (e.g. Dependable) has an all-zero Q and a single 1 in `w` at its
 * one load-bearing channel's index; a compound trait (e.g. Caretaker) can
 * combine several. Named traits are NOT independent state — the
 * authoritative state remains `IdentityEvidenceState`; the trait is a
 * semantic label recognizing a pattern already present there (Brief §21
 * "Important"). */
export interface IdentityTrait {
  readonly traitId: string;
  readonly b: Rational;
  readonly w: Vec;
  readonly Q: Matrix;
}

export function projectTrait(trait: IdentityTrait, I: Vec): Rational {
  return Rational.boundedResponse(quadraticForm(trait.b, trait.w, trait.Q, I));
}

/** A trait "may be considered consolidated" (Brief §21) when its projected
 * value clears θ_trait AND its confidence clears θ_confidence. A compound
 * trait's confidence is the MINIMUM confidence among the channels it
 * actually depends on (nonzero w_j or a nonzero Q_j row/column) — the
 * trait cannot be more confident than its least-evidenced necessary
 * component; a channel the trait doesn't reference at all doesn't gate it. */
export function isConsolidated(
  trait: IdentityTrait,
  I: Vec,
  evidenceByChannel: ReadonlyMap<IdentityExpressionChannelId, IdentityEvidenceState>,
  kC: Rational,
  thetaTrait: Rational,
  thetaConfidence: Rational,
): boolean {
  const value = projectTrait(trait, I);
  const relevantChannels = CHANNEL_ORDER.filter(
    (_, idx) => !trait.w[idx].isZero() || trait.Q[idx].some((q) => !q.isZero()),
  );
  const confidences = relevantChannels.map((c) => identityConfidence(evidenceByChannel.get(c) ?? EMPTY_IDENTITY_EVIDENCE, kC));
  const confidence = confidences.length === 0 ? Rational.ZERO : confidences.reduce((a, b) => a.min(b));
  return value.gte(thetaTrait) && confidence.gte(thetaConfidence);
}

// Phase 2.95 — Reason Consolidation, with identity genuinely IN the pool.
//
// Step 1: collect each Option's raw (unbounded) Need/accessibility
// pressure, and separately sum it per semantic channel — NOT yet bounded,
// NOT yet floor-checked. `boundedNeedAccessByOption` is the same sum run
// through `boundAllChannels` (dense, bounded, but NOT floor-filtered) —
// this is what identity.ts's Alignment/touchedChannels consume for
// EVIDENCE generation, deliberately excluding identity's own feedback
// (Brief §23's no-double-counting rule: a Decision's identity-consistency
// reason is derived from existing identity, not fresh behavioral
// evidence, so it must never feed the computation that produces MORE
// evidence for the same channel).
const rawNeedAccessByOption = new Map<CanonicalActionKey, RawReasonInfluence[]>();
const rawSumByOption = new Map<CanonicalActionKey, Map<SemanticReasonChannelId, Rational>>();
const boundedNeedAccessByOption = new Map<CanonicalActionKey, Map<SemanticReasonChannelId, Rational>>();
// Phase 2.97: retained alongside the SemanticReasonChannelId sums above so
// the 'reasonNuclei' branch of Step 2 (below) can build RawCognitiveSignals
// from the SAME already-computed ScoredAction/accessibility this loop
// produces for every Option, rather than recomputing either.
const scoredByOption = new Map<CanonicalActionKey, ScoredAction>();
const accessibilityByOption = new Map<CanonicalActionKey, Rational>();
for (const option of decision.options) {
  const scored = evaluateAction(
    option.actionDef,
    ctxs,
    (needId) => getExpectation(stateForEvaluation, option.actionDef.subject, needId),
    params.expectation.kC,
  );
  scoredByOption.set(option.actionDef.actionKey, scored);

  const rawInfluences: RawReasonInfluence[] = [];
  for (const c of scored.perNeedContributions) {
    rawInfluences.push({
      source: 'need_contribution',
      reasonChannel: c.needId,
      strength: c.contribution,
    });
  }
  const accessibility = activation.get(asConceptKey(option.actionDef.actionKey)) ?? Rational.ZERO;
  accessibilityByOption.set(option.actionDef.actionKey, accessibility);
  rawInfluences.push({
    source: 'accessibility',
    reasonChannel: REASON_CHANNEL_ACCESSIBILITY,
    strength: accessibility,
  });

  const rawSum = sumRawBySemanticChannel(rawInfluences, reasonChannelMapping);
  rawNeedAccessByOption.set(option.actionDef.actionKey, rawInfluences);
  rawSumByOption.set(option.actionDef.actionKey, rawSum);
  boundedNeedAccessByOption.set(option.actionDef.actionKey, boundAllChannels(rawSum));

  trace.record(
    'decision_influences_raw_needs_accessibility',
    { optionKey: option.actionDef.actionKey },
    {
      rawInfluences: rawInfluences.map((r) => ({
        source: r.source,
        reasonChannel: r.reasonChannel,
        strength: r.strength.toCanonicalString(),
      })) as any,
    },
  );
}

// Step 2: when identity feedback is enabled, decompose each Option's
// identity pull into ONE raw contribution PER semantic channel (Alignment
// computed from `boundedNeedAccessByOption` above — never including
// identity's own contribution) and fold each into the SAME raw pool as
// that option's own Need/accessibility pressure on that channel, BEFORE
// the shared bound-and-floor step. This is the actual Phase 2.95
// mechanism: a weak Need signal and a weak identity signal sharing a
// semantic channel now get ONE shared chance to clear the floor together,
// rather than identity being a second, independently-floored influence
// that can never rescue (or be rescued by) a Need signal too weak on its
// own — see identity.ts's module comment for the full derivation.

describe('Named trait projection and consolidation (Brief §21)', () => {
  const dependableIdx = CHANNEL_ORDER.indexOf('CommitmentFidelity');
  const dependableTrait: IdentityTrait = {
    traitId: 'trait.dependable',
    b: Rational.ZERO,
    w: CHANNEL_ORDER.map((_, i) => (i === dependableIdx ? Rational.ONE : Rational.ZERO)),
    Q: CHANNEL_ORDER.map(() => CHANNEL_ORDER.map(() => Rational.ZERO)),
  };

  it('projectTrait reduces to boundedResponse(IdentityStrength_CommitmentFidelity) for a pure single-channel trait', () => {
    const I = CHANNEL_ORDER.map((c) => (c === 'CommitmentFidelity' ? ratOf(6, 10) : Rational.ZERO));
    const projected = projectTrait(dependableTrait, I);
    expect(projected.equals(Rational.boundedResponse(ratOf(6, 10)))).toBe(true);
  });

  it('is NOT consolidated when strength clears the threshold but confidence does not', () => {
    const I = CHANNEL_ORDER.map((c) => (c === 'CommitmentFidelity' ? ratOf(9, 10) : Rational.ZERO));
    const evidence = new Map([['CommitmentFidelity' as const, { support: ratOf(1, 100), opposition: Rational.ZERO }]]);
    expect(isConsolidated(dependableTrait, I, evidence, KC, ratOf(3, 10), ratOf(5, 10))).toBe(false);
  });

  it('IS consolidated once both strength and confidence clear their thresholds', () => {
    const I = CHANNEL_ORDER.map((c) => (c === 'CommitmentFidelity' ? ratOf(9, 10) : Rational.ZERO));
    const evidence = new Map([['CommitmentFidelity' as const, { support: ratOf(100), opposition: Rational.ZERO }]]);
    expect(isConsolidated(dependableTrait, I, evidence, KC, ratOf(3, 10), ratOf(5, 10))).toBe(true);
  });

  it('a channel the trait does not reference does not gate its confidence', () => {
    const I = CHANNEL_ORDER.map((c) => (c === 'CommitmentFidelity' ? ratOf(9, 10) : Rational.ZERO));
    // Zero evidence for every OTHER channel, plenty for CommitmentFidelity.
    const evidence = new Map(CHANNEL_ORDER.map((c) => [c, c === 'CommitmentFidelity' ? { support: ratOf(100), opposition: Rational.ZERO } : EMPTY_IDENTITY_EVIDENCE]));
    expect(isConsolidated(dependableTrait, I, evidence, KC, ratOf(3, 10), ratOf(5, 10))).toBe(true);
  });
});

